14	    private static final ObjectMapper MAPPER = new ObjectMapper();
15	    private static final String ALIVE_CELLS = "aliveCells";
16	    private static final String STEPS = "steps";
17	
18	    private GameOfLifeCli() {
19	    }
20	
21	    public static void main(String[] args) throws IOException {
22	        JsonNode request = MAPPER.readTree(System.in);
23	        Set<Cell> livingCells = new GameOfLife()
24	                .advance(readLivingCells(request.get(ALIVE_CELLS)), request.get(STEPS).asInt());
25	        System.out.print(MAPPER.writeValueAsString(writeLivingCells(livingCells)));
26	    }
