28	    private static Set<Cell> readLivingCells(JsonNode aliveCells) {
29	        Set<Cell> livingCells = new LinkedHashSet<>();
30	        for (JsonNode cell : aliveCells) {
31	            livingCells.add(new Cell(cell.get(0).asInt(), cell.get(1).asInt()));
32	        }
33	        return livingCells;
34	    }
