36	    private static List<Cell> sortedByXThenY(Set<Cell> livingCells) {
37	        List<Cell> sorted = new ArrayList<>(livingCells);
38	        sorted.sort(Comparator.comparingInt(Cell::x).thenComparingInt(Cell::y));
39	        return sorted;
40	    }
41	
42	    private static ObjectNode writeLivingCells(Set<Cell> livingCells) {
43	        ObjectNode response = MAPPER.createObjectNode();
44	        ArrayNode cells = response.putArray(ALIVE_CELLS);
45	        for (Cell cell : sortedByXThenY(livingCells)) {
46	            cells.addArray().add(cell.x()).add(cell.y());
47	        }
48	        return response;
49	    }
50	}
