4	public class GameOfLife {
5	
6	    public Set<Cell> advance(Set<Cell> livingCells, int generations) {
7	        Set<Cell> current = livingCells;
8	        for (int generation = 0; generation < generations; generation++) {
9	            current = nextGeneration(current);
10	        }
11	        return current;
12	    }
13	
14	    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
15	        Set<Cell> next = new LinkedHashSet<>();
16	        for (Cell cell : cellsThatMayChange(livingCells)) {
17	            if (isAliveNextGeneration(cell, livingCells)) {
18	                next.add(cell);
19	            }
20	        }
21	        return next;
22	    }
23	
24	    private boolean isAliveNextGeneration(Cell cell, Set<Cell> livingCells) {
25	        int livingNeighbours = countLivingNeighbours(cell, livingCells);
26	        return livingCells.contains(cell)
27	                ? survives(livingNeighbours)
28	                : isBorn(livingNeighbours);
29	    }
30	
31	    /**
32	     * On an infinite grid only a living cell or a cell adjacent to one can change state, so
33	     * these are the only cells the transition rules have to be asked about.
34	     */
35	    private Set<Cell> cellsThatMayChange(Set<Cell> livingCells) {
36	        Set<Cell> mayChange = new LinkedHashSet<>(livingCells);
37	        for (Cell cell : livingCells) {
38	            mayChange.addAll(cell.neighbours());
39	        }
40	        return mayChange;
41	    }
42	
43	    private boolean survives(int livingNeighbours) {
44	        return livingNeighbours == 2 || livingNeighbours == 3;
45	    }
46	
47	    private boolean isBorn(int livingNeighbours) {
48	        return livingNeighbours == 3;
49	    }
50	
51	    private int countLivingNeighbours(Cell cell, Set<Cell> livingCells) {
52	        int count = 0;
53	        for (Cell neighbour : cell.neighbours()) {
54	            if (livingCells.contains(neighbour)) {
55	                count++;
56	            }
57	        }
58	        return count;
59	    }
60	}
